type CartBadgeProps = {
  itemCount: number;
};

export function CartBadge({ itemCount }: CartBadgeProps) {
  if (itemCount <= 0) {
    return null;
  }

  const label = itemCount > 99 ? "99+" : String(itemCount);

  return <span className="cart-badge">{label}</span>;
}

